mkfile packages/nft-attestation/metadatabuilder.py
mkfile packages/nft-attestation/minter.py
mkfile packages/nft-attestation/custody.py

# Packages: playbook-engine
mkfile packages/playbook-engine/__init__.py
mkfile packages/playbook-engine/schema.py
mkfile packages/playbook-engine/executor.py
mkfile packages/playbook-engine/triggerengine.py
mkfile packages/playbook-engine/blastradius.py
for f in storageactions cryptoactions agentactions nftactions networkactions; do
  mkfile "packages/playbook-engine/actions/${f}.py"
done
mkfile packages/playbook-engine/library/lockdownlattice.yaml
