done

# Policy files
for ring in unclass sensitive classified topsecret ts_sci; do
  mkfile "configs/policies/${ring}.yaml"
done

# Agent configs
for agent in sentinel strategist archivist executor; do
  mkfile "configs/agents/${agent}.yaml"
