mkfile infra/otel/otel-collector-config.yaml
mkfile infra/grafana/dashboards/warlab-overview.json
mkfile infra/istio/peer-authentication.yaml

# Docs: module specs & runbooks
for f in 0101PQCARCH 0202KEYROTATION 0303SHARDVAULT 0404THREATBOARD 0505REDTEAM 0606ZKPROOF 0707NFTMINT 0808AIPIPELINE 0909OSINTFUSION 1010FEDERATEDNODE 1111SOVEREIGNDATABASE 1212CODINGTUTOR; do
  mkfile "docs/modules/${f}.md"
done
mkfile docs/runbooks/operations.md
mkfile docs/runbooks/incidents.md
mkfile docs/runbooks/playbooks.md
mkfile docs/diagrams/architecture.md

# Runtime dirs (no files)
mkdir -p data/postgres data/redis data/ipfs data/vector data/registry
mkdir -p logs/api logs/agents logs/audit logs/security logs/otel
mkdir -p backups/snapshots backups/shards backups/config backups/memory-graph
mkdir -p artifacts/nft artifacts/proofs artifacts/reports artifacts/manifests
mkdir -p secrets

# Scripts
mkfile scripts/quantumthreatscan.py
mkfile scripts/keyceremony.py
mkfile scripts/deaddropvault.py
mkfile scripts/codexconsole.py
mkfile scripts/redteam/redteam_nft_vault_tests.py
mkfile scripts/redteam/redteam_storage_mesh_tests.py
mkfile scripts/redteam/redteam_agent_consensus_tests.py
mkfile scripts/redteam/redteam_pqc_tests.py
mkfile scripts/redteam/redteam_runner.py
mkfile scripts/simulation/scenario_builder.py
mkfile scripts/simulation/adversary_emulator.py
mkfile scripts/simulation/observer.py
mkfile scripts/simulation/report_generator.py
mkfile scripts/simulation/runner.py

# Final message
cat << EOF
[CodexImmortal] Directory scaffold created.
Root: $(pwd)
Next:
  - Fill package and app files with implementations.
  - Wire configs to services.
  - Add dependency files (requirements.txt, package.json) per package.
EOF